$ErrorActionPreference = "Stop"
$ProgressPreference = "SilentlyContinue"

# Output-channel hygiene (batch 3): child-process output must not double-garble
# on non-UTF8 consoles. Force UTF-8 output encoding up front; the original
# codepage is kept for diagnostics (the batch-4 banner itself is pure ASCII
# and never depends on the console codepage).
$script:OriginalOutputCP = try { [Console]::OutputEncoding.CodePage } catch { 0 }
try {
    [Console]::OutputEncoding = [System.Text.Encoding]::UTF8
    $OutputEncoding = [System.Text.Encoding]::UTF8
} catch {}

# Nebflow Windows installer - script v2
# ---------------------------------------------------------------
# ScriptVersion : installer version (written into the local install
#                 manifest for `nebflow update` and diagnostics).
# Pipeline      : [1/7] java -> [2/7] git -> [3/7] jar -> [4/7] rg ->
#                 [5/7] voice model -> [6/7] launcher -> [7/7] config.
# Idempotent    : safe to re-run; installed/satisfied deps are detected
#                 and skipped.
# Flags         : -Beta | --channel=beta | -Cn | -Global | -VerboseFlag
#                 (irm|iex pipe: env CHANNEL=beta / REGION=cn /
#                 NEBFLOW_VERBOSE=1)
# Exit codes    : 0 ok | 10 version resolve | 11 java install |
#                 12 jar download
# ---------------------------------------------------------------

# -- Brand values (L2 rebrand): rendered from repo-root brand.conf at -------
# -- release time (scripts/render-brand.sh); do not edit by hand. -----------
# The runtime dual-reads legacy names (L3), so rendering NEW values here
# keeps existing user data working - old dirs/env/config fall back.
$ProductName = "stand"
$LowerName = "stand"
$CosBucket = "nebflow-releases"
$HomeDir = ".stand"
# Install base (zaisheng-zhiben batch 2026-10-22): STAND_HOME is the first-priority base;
# default is USERPROFILE + brand home. NEBFLOW_HOME is never consulted here -
# the installer never writes the legacy root (legacy read-only is runtime-only).
$StandBase = if ($env:STAND_HOME) { $env:STAND_HOME } else { Join-Path $env:USERPROFILE $HomeDir }
$ConfigFile = "nebflow.json"
$WrapperName = "stand"
$CosBaseCn = "https://$CosBucket.oss-cn-hangzhou.aliyuncs.com"
# Single-source conclusion unchanged: the Nebflow jar download and the version
# resolution go through the mirror endpoint above (same value as the CI upload
# tracks and the deployed online script). Stale reason corrected (2026-09-17):
# this used to read "repo went private (#29, 2026-09-01) -> unauthenticated
# GitHub Releases downloads 404" - the repo is public again, so that reason no
# longer holds and no GitHub fallback path is kept; the single source stays for
# reachability and bandwidth (direct GitHub downloads are not usable in
# practice). Third-party deps (Temurin JDK / Git for Windows / ripgrep) are
# unrelated to the repo visibility and keep their public sources.

$ScriptVersion = "2.0.0"
$RgVersion = "14.1.1"
$JdkMajorRequired = 21   # runtime floor
# Batch 2 (v2): all third-party deps mirrored on COS under the deps/ prefix
# (single primary source for every region; upstream sources demoted to
# fallback). Integrity via deps/checksums.txt (sha256, generated by
# scripts/upload-deps.sh at upload time).
$CosDepsBase = "$CosBaseCn/deps"

# ---- checksum machinery (deps/ integrity, batch 2) ------------------------
$script:ChecksumsContent = $null
$script:ChecksumsState = ""      # "ok" | "unreachable" | "unparseable"
$script:LastUnknownReason = ""   # manifest-unreachable|manifest-unparseable|no-sha-tool|not-in-manifest

# Integrity-verification policy for third-party deps (NEBFLOW_VERIFY env,
# default warn):
#   strict = refuse unverified artifacts (the download fails when no usable
#            checksum can be obtained from deps/checksums.txt)
#   warn   = proceed, but print a VISIBLE warning for every unverified
#            artifact - degraded verification is never silent
#   off    = skip verification entirely (a one-time notice is still printed)
$script:VerifyMode = if ($env:NEBFLOW_VERIFY) { "$env:NEBFLOW_VERIFY".ToLowerInvariant() } else { "warn" }
if ($script:VerifyMode -ne "strict" -and $script:VerifyMode -ne "warn" -and $script:VerifyMode -ne "off") {
    $script:VerifyMode = "warn"
}

function Get-ExpectedChecksum($name) {
    if ($null -eq $script:ChecksumsContent) {
        $script:ChecksumsContent = ""
        try {
            $raw = (Invoke-WebRequest -Uri "$CosDepsBase/checksums.txt" -UseBasicParsing -TimeoutSec 15).Content
            # Keep only well-formed "sha256  name" rows: a fetched-but-garbage
            # body must degrade as "unparseable" (a visible warning), never as
            # a working manifest that silently verifies nothing.
            $rows = @("$raw" -split "`n" | Where-Object { $_ -match '^[0-9a-fA-F]{64}\s+\S+$' })
            if ($rows.Count -gt 0) {
                $script:ChecksumsContent = $rows -join "`n"
                $script:ChecksumsState = "ok"
                Write-V "Loaded deps/checksums.txt from the mirror."
            } else {
                $script:ChecksumsState = "unparseable"
                Write-V "deps/checksums.txt fetched but unparseable - checksum verification degraded."
            }
        } catch {
            $script:ChecksumsState = "unreachable"
            Write-V "deps/checksums.txt unreachable - checksum verification degraded."
        }
    }
    if ($script:ChecksumsState -ne "ok") { return $null }
    foreach ($line in ($script:ChecksumsContent -split "`n")) {
        $parts = $line.Trim() -split '\s+', 2
        if ($parts.Count -eq 2 -and $parts[1] -eq $name) { return $parts[0].ToLower() }
    }
    return $null
}

# Returns "ok" | "bad" | "unknown" (on "unknown" also sets
# $script:LastUnknownReason so the policy gate can warn precisely)
function Test-FileChecksum($path, $name) {
    $expected = Get-ExpectedChecksum $name
    if (-not $expected) {
        if ($script:ChecksumsState -eq "ok") { $script:LastUnknownReason = "not-in-manifest" }
        elseif ($script:ChecksumsState -eq "unparseable") { $script:LastUnknownReason = "manifest-unparseable" }
        else { $script:LastUnknownReason = "manifest-unreachable" }
        return "unknown"
    }
    try {
        $actual = (Get-FileHash -Path $path -Algorithm SHA256).Hash.ToLower()
    } catch {
        $script:LastUnknownReason = "no-sha-tool"
        return "unknown"
    }
    if ($actual -eq $expected) { Write-V "Checksum OK: $name"; return "ok" }
    Write-Warn2 "Checksum mismatch for $name (expected $expected, got $actual)"
    return "bad"
}

# Policy gate for "no verification possible" verdicts (NEBFLOW_VERIFY).
# Returns $true when the install may proceed despite the unverified file;
# $false = refuse it (strict), so Get-FileFromSources tries the next source.
function Accept-Unverified($name) {
    if ($script:VerifyMode -eq "off") {
        if (-not $script:VerifyOffNoted) {
            Write-Warn2 "Integrity verification disabled by NEBFLOW_VERIFY=off - downloads are NOT checksum-verified."
            $script:VerifyOffNoted = $true
        }
        return $true
    }
    if ($script:VerifyMode -eq "strict") { return $false }
    switch ($script:LastUnknownReason) {
        "manifest-unreachable" {
            if (-not $script:VerifyWarnManifestNoted) {
                Write-Warn2 "Checksum manifest unreachable ($CosDepsBase/checksums.txt) => this install performs NO integrity verification on third-party deps."
                Write-Warn2 "Fix the mirror and re-run, or set NEBFLOW_VERIFY=strict to refuse unverified installs."
                $script:VerifyWarnManifestNoted = $true
            }
        }
        "manifest-unparseable" {
            if (-not $script:VerifyWarnManifestNoted) {
                Write-Warn2 "Checksum manifest fetched but unparseable ($CosDepsBase/checksums.txt) => this install performs NO integrity verification on third-party deps."
                Write-Warn2 "Fix the mirror and re-run, or set NEBFLOW_VERIFY=strict to refuse unverified installs."
                $script:VerifyWarnManifestNoted = $true
            }
        }
        "no-sha-tool" {
            Write-Warn2 "No SHA-256 support available - cannot verify $name; installed unverified. Set NEBFLOW_VERIFY=strict to refuse unverified installs."
        }
        default {
            Write-Warn2 "$name has no entry in deps/checksums.txt - installed unverified. Set NEBFLOW_VERIFY=strict to refuse unverified installs."
        }
    }
    return $true
}

function Write-ChecksumHint($name) {
    $h = Get-ExpectedChecksum $name
    if ($h) { Write-Warn2 "       sha256: $h" }
}

# --- download progress (batch 4 redesign) ------------------------------------
# Buffered HttpWebRequest copy with a native Write-Progress bar: percentage
# only when Content-Length is known (unknown length -> byte count only,
# never a fake percentage). Redirected output (irm|iex pipe): plain log
# lines, no progress control at all.
function Save-WithProgress {
    param([string]$Url, [string]$Path, [string]$Label)
    $interactive = -not [Console]::IsOutputRedirected
    if (-not $Label) { $Label = [System.IO.Path]::GetFileName($Path) }
    if (-not $interactive) { Write-Info "Downloading $Label..." }
    $req = [System.Net.HttpWebRequest]::Create($Url)
    $req.Timeout = 600000
    $req.ReadWriteTimeout = 600000
    $req.UserAgent = "$ProductName-installer/$ScriptVersion"
    # Some sources (npmmirror) answer with 302s pointing at their CDN:
    # redirects must be followed explicitly - a bare redirect page is NOT
    # the artifact (108-byte HTML would otherwise pass as a download).
    $req.AllowAutoRedirect = $true
    $req.MaximumAutomaticRedirections = 8
    $resp = $req.GetResponse()
    try {
        $total = $resp.ContentLength
        $inStream = $resp.GetResponseStream()
        $outStream = [System.IO.File]::Create($Path)
        $savedPP = $ProgressPreference
        try {
            $buf = New-Object byte[] 65536
            $doneBytes = 0L
            $ProgressPreference = "Continue"
            while (($n = $inStream.Read($buf, 0, $buf.Length)) -gt 0) {
                $outStream.Write($buf, 0, $n)
                $doneBytes += $n
                if ($interactive) {
                    if ($total -gt 0) {
                        $pct = [math]::Min(100, [int]($doneBytes * 100.0 / $total))
                        $status = ("{0:N1}/{1:N1} MB" -f ($doneBytes / 1MB), ($total / 1MB))
                        Write-Progress -Activity "Downloading $Label" -Status $status -PercentComplete $pct
                    } else {
                        Write-Progress -Activity "Downloading $Label" -Status ("{0:N1} MB" -f ($doneBytes / 1MB))
                    }
                }
            }
        } finally {
            $ProgressPreference = $savedPP
            $outStream.Dispose()
        }
    } finally {
        $resp.Dispose()
    }
    if ($interactive) { Write-Progress -Activity "Downloading $Label" -Completed }
    else { Write-Ok "Downloaded $Label." }
}

# Multi-source download with checksum verification (COS first by convention).
#   Get-FileFromSources -Path <target> -Name <manifest-name> -Urls <url,...> [-Label <ui-name>]
# Returns $true when a source succeeded (checksum ok or unknown).
function Get-FileFromSources {
    param([string]$Path, [string]$Name, [string[]]$Urls, [string]$Label)
    foreach ($url in $Urls) {
        Write-V "Trying source: $url"
        try {
            Save-WithProgress -Url $url -Path $Path -Label $(if ($Label) { $Label } else { $Name })
        } catch {
            Remove-Item $Path -Force -ErrorAction SilentlyContinue
            continue
        }
        if (-not (Test-Path $Path)) { continue }
        $verdict = Test-FileChecksum $Path $Name
        if ($verdict -eq "bad") {
            Remove-Item $Path -Force -ErrorAction SilentlyContinue
            continue
        }
        if ($verdict -eq "unknown" -and -not (Accept-Unverified $Name)) {
            # strict policy: refuse the unverified artifact, try the next source
            Remove-Item $Path -Force -ErrorAction SilentlyContinue
            continue
        }
        return $true
    }
    return $false
}

# -- unified log helpers ----------------------------------------------------
$VerbosePref = ($env:NEBFLOW_VERBOSE -eq "1")
function Write-Info($m)  { Write-Host "[i] $m" }
function Write-Ok($m)    { Write-Host "[ok] $m" -ForegroundColor Green }
function Write-Warn2($m) { Write-Host "[warn] $m" -ForegroundColor Yellow }
function Write-Err2($m)  { Write-Host "[err] $m" -ForegroundColor Red }
function Write-V($m)     { if ($VerbosePref) { Write-Host "[v] $m" -ForegroundColor DarkGray } }
function Write-Stage($n, $total, $m) { Write-Host ""; Write-Host "==> [$n/$total] $m" -ForegroundColor Yellow }

# Parse flags
$Channel = if ($env:CHANNEL) { $env:CHANNEL } else { "stable" }
$Region = ""
# Also check command-line args (for direct execution, not via iex)
if ($args -contains "-Beta") { $Channel = "beta" }
if ($args -contains "--channel=beta") { $Channel = "beta" }
if ($args -contains "-VerboseFlag") { $VerbosePref = $true }
if ($args -contains "-Cn") { $Region = "cn" }
if ($args -contains "-Global") { $Region = "global" }

# --- Brand banner: the OFFICIAL stand-horizontal lockup, dual path ----------
# The banner reproduces the OFFICIAL stand-horizontal lockup (symbol +
# wordmark, the composition the website navbar renders). DUAL PATH
# (2026-10-22 image-protocol batch), same official payloads as install.sh:
#
#   image path - the REAL logo raster when the terminal speaks an
#     inline-image protocol: OSC 1337 (iTerm2 / WezTerm / mintty /
#     Konsole >= 22.04) via $BannerPngDark/Light (base64 PNG, width/height
#     declared in CELLS pins it onto the art grid), or SIXEL (Windows
#     Terminal >= 1.22 via WT_SESSION - sixel stable in WT since 2025-04;
#     older WT silently consumes the DCS and the version line still
#     renders, so degradation stays clean) via $BannerSixelDark/Light
#     (pre-encoded body, DCS/ST framing added at runtime - pure printable
#     ASCII in the file). P2=1 keeps unpainted pixels transparent.
#   art fallback - U+2580/U+2584/U+2588 half-block glyphs driven by
#     $BannerArt (auto-sampled from the authoritative Illustrator-kit SVGs
#     by scripts/render-install-banner.py - rasterize -> alpha-coverage
#     threshold -> half-block cells -> RLE; no hand-drawn approximation,
#     author mandate 2026-10-22: the retired 4x3 green-pixel "S" mask did
#     not match the brand - no green remains; the kit is pure monochrome
#     ink). Old conhost / dumb pipes / every terminal without an image
#     protocol render this path, so PS 5.1 conhost behaviour is byte-for-
#     byte the pre-batch one.
#
# $BannerArt is a 1-bit coverage grid of the lockup, run-length encoded as
# <count><cell> tokens with rows joined ';'. Cell codes: '.' empty, 'u' ink
# upper half, 'n' ink lower half, '#' ink full cell. Ink is painted with the
# FOREGROUND color so the terminal's own background shows through - the art
# keeps the kit's transparency on every terminal. $BannerInkDark/Light are
# the two kit variants' true fill values (24-bit truecolor): white-ink
# variant on dark terminals, black-ink variant on light terminals.
# Anti-drift: scripts/check-logo-matrix.py re-derives ALL embedded payloads
# from the SVGs and asserts both installers embed them byte-identically.
# Degrade chain (art path): VT truecolor fg (PS 7+ / Windows Terminal) -> 16-color
# console fg (PS 5.1 conhost, zero escape risk) -> plain uncolored half-block
# render (NO_COLOR / CI / redirected output - the glyphs stay: they exist in
# CP437 and in every console font since the IBM PC, and the script forces
# UTF-8 output encoding). Every level keeps the shape.
# Width: 72 cells + 2-space indent = 74 columns, inside the 80-column
# floor. The grid is 72 columns x 9 half-block rows (each cell carries two
# pixel rows), physically 4:1 - a cell is ~2x taller than wide - reproducing
# the lockup's 4.007:1 aspect. The image payloads target the same footprint
# (OSC 1337 declares 72x9 CELLS; the sixel canvas is 576x~144 px = 72x9
# cells at an ~8x16 cell raster).
# Theme: NEBFLOW_BANNER_THEME=dark|light overrides; else COLORFGBG's
#   background field (>=7 = light background); default dark.
# Image: NEBFLOW_BANNER_IMAGE=off -> force the art path; =osc|sixel ->
#   force that protocol (testing; bypasses every guard); unset -> auto-
#   detect. Auto honors NO_COLOR/CI/TERM=dumb/output-redirected - a
#   redirected pipe never swallows sixel/OSC bytes.
# Level: NEBFLOW_UI_LEVEL=0..3 forces a level; PS 7+/WT_SESSION -> 3, PS 5.1
#   conhost -> 1, NO_COLOR/CI/redirected -> 0.
# Dry: -BannerOnly / NEBFLOW_BANNER_ONLY=1 renders the banner and exits
#   right here - before version resolution (no network) and before any
#   install side effect.
# Batch 3 invariant holds: this section stays PURE ASCII after the UTF-8
# BOM - the payloads are digits + '.'/u/n/# / base64 / printable sixel; the
# block glyphs and every escape byte are produced at runtime via [char].
# --- BANNER-ART-BEGIN (generated by scripts/render-install-banner.py -- do not hand-edit) ---
# Official stand-horizontal lockup (symbol + wordmark), auto-sampled
# from src/main/resources/web/brand/stand/illustrator/svg/ by
# scripts/render-install-banner.py (1-bit coverage, RLE cells:
# '.' empty | 'u' top | 'n' bottom | '#' full; rows joined ';').
# Pure-ASCII invariant holds: the u/n/# payload never contains the
# block glyphs themselves - Write-Banner emits them via [char]; the
# image payloads are base64/printable-ASCII, the OSC/DCS escape bytes
# are produced at runtime via [char]27.
$BannerArt = "15.5n52.;9.3n5#2u53.;5.2n4#3u11.7n2.8n3.2n5.1n6.2n1.8n2.;2.1n5#1u15.2#5u2.3u2#3u2.1n3#1n4.3#1n3.2#1.2#5u2#1.;2.5#3.3u4#2n5.6u2#1n3.2#4.2#1u2.2#1n2.2#2u1#2n2#1.2#5.2#1.;3.7u3.1n5#4.2n7#1u3.2#2.1n1#1u5.1u1#1n1.2#3.1u3#1.8#1u1.;9.2n5#2u54.;3.2n6#3u58.;2.5u65."
$BannerInkDark = "255;255;255"    # white-ink kit variant (dark terminals)
$BannerInkLight = "0;0;0"      # black-ink kit variant (light terminals)
$BannerPngDark = ""
$BannerPngLight = ""
$BannerSixelDark = '"1;1;576;144#1;2;100;100;100-!576?-!126?!5_!5o!5w!7{!11}~~~^NNFB@!408?-!104?___ooo!4w!4{!4}!33~^NFBB@!415?-!85?___ooowww{{{!4}!44~^^^NFFB@!423?-!70?__oooww{{{}}}!43~^^^NNN!4FBBB@@@!434?-!56?___ooww{{}}!42~^^^NNNFFFBBB@@!453?-!45?_ooww{{}}!40~^^NNNFFBBB@@!470?-!35?_oow{{}}!38~^^NNFFBB@@@!104?_oowww!55{[KC!5?_ow!66{[KC!19?_o!16{o_!39?!13{wo__!42?!13{!5?CK!65{wwoo_!12?-!27?_ow{{}!37~^^NFFBB@@!112?_o{}!54~^NNFB@!5?_ow{}!63~^NFB@!18?_ow}!22~{w_!35?!18~}{{wo_!35?!13~!8?@BF!67~}wo!8?-!20?_ow{}!37~^NFBB@!122?w!14~NBB!40@!11?!31@B!13~!23@!19?_ow}!13~^NFN!14~}wo_!30?!26~}{woo_!27?!13~!11?!14~!36@BBBFN^!15~{!6?-!16?_o{}!36~^FB@!27?!5_!5o!25w!4o!5_!59?N!14~}{w!43o__!38?!13~!37?_ow{!14~NFB@!5?@BN^!13~}{w_!26?!13~BFNN^!15~}}{wo__!19?!13~!11?!14~!43?!15~!6?-!15?{!37~^B!18?_ooWW[[[]]M!10N!7^!34~}}{{{wwo__!46?@FN^!60~}{w_!32?!13~!33?ow{}!13~^NB@!15?BFN!14~{wo!22?!13~!6?@@BFNN^!15~}{wwo_!12?!13~!11?!14~!43?!15~!6?-!15?N!37~{_!49?@@BFFN!36~}{wo!46?@BBB!42FNN^!14~}!31?!13~!28?ow{}!13~^NF@!24?@BN^!13~}{o_!17?!13~!14?@@BFNN^!15~}{woo_!4?!13~!11?!14~!43?!15~!6?-!17?@BNN^!34~}}{wwwooo!6_!12?!7_oOO!18?v!39~w!91?_o!15~!31?!13~!23?_w{}!13~^NFB!34?BFN!13~}{w_!13?!13~!22?@@BFNN^!14~}{{!13~!11?!14~!38?__ow}!14~^!6?-!24?@BBBFFNNN!5^!35~!4^!4NFFFBBB@@!18?_ow}!38~^N!40?__ow{{}!59~^NB!31?!12~^!18?_o{}!14~NFB@!42?@BN^!13~}wo_!8?!13~!30?@@BFNN^!22~!11?!67~^NF@!7?-!43?!23@!33?__oow{}!39~^NF@!34?_oow{}}!58~^^^NNFB@@!34?!5~^NNFB@!15?ow{}!14~^FB@!52?BFN^!12~}{o_!4?!13~!38?@BBFN^^!14~!11?^!56~^^^NNFBB@!12?-!88?__ooww{{}!41~^NFFB@!147?NFB@!281?-!72?___oooww{{{}}!43~^NNFFBB@!440?-!53?!4_ooowww{{{}}}!46~^^NNFFBB@@@!450?-!33?___!4owww!4{}}}!49~^^^NNFFFBBB@@!464?-!21?_oww{}}}!50~^^^!4NFFFBBB@@@!481?-!13?__ow{}}!35~!4^!4N!4F!5B@@@!501?-!7?oow{}~~!12^!7N!7F!5B!5@!526?-!576?'
$BannerSixelLight = '"1;1;576;144#1;2;0;0;0-!576?-!126?!5_!5o!5w!7{!11}~~~^NNFB@!408?-!104?___ooo!4w!4{!4}!33~^NFBB@!415?-!85?___ooowww{{{!4}!44~^^^NFFB@!423?-!70?__oooww{{{}}}!43~^^^NNN!4FBBB@@@!434?-!56?___ooww{{}}!42~^^^NNNFFFBBB@@!453?-!45?_ooww{{}}!40~^^NNNFFBBB@@!470?-!35?_oow{{}}!38~^^NNFFBB@@@!104?_oowww!55{[KC!5?_ow!66{[KC!19?_o!16{o_!39?!13{wo__!42?!13{!5?CK!65{wwoo_!12?-!27?_ow{{}!37~^^NFFBB@@!112?_o{}!54~^NNFB@!5?_ow{}!63~^NFB@!18?_ow}!22~{w_!35?!18~}{{wo_!35?!13~!8?@BF!67~}wo!8?-!20?_ow{}!37~^NFBB@!122?w!14~NBB!40@!11?!31@B!13~!23@!19?_ow}!13~^NFN!14~}wo_!30?!26~}{woo_!27?!13~!11?!14~!36@BBBFN^!15~{!6?-!16?_o{}!36~^FB@!27?!5_!5o!25w!4o!5_!59?N!14~}{w!43o__!38?!13~!37?_ow{!14~NFB@!5?@BN^!13~}{w_!26?!13~BFNN^!15~}}{wo__!19?!13~!11?!14~!43?!15~!6?-!15?{!37~^B!18?_ooWW[[[]]M!10N!7^!34~}}{{{wwo__!46?@FN^!60~}{w_!32?!13~!33?ow{}!13~^NB@!15?BFN!14~{wo!22?!13~!6?@@BFNN^!15~}{wwo_!12?!13~!11?!14~!43?!15~!6?-!15?N!37~{_!49?@@BFFN!36~}{wo!46?@BBB!42FNN^!14~}!31?!13~!28?ow{}!13~^NF@!24?@BN^!13~}{o_!17?!13~!14?@@BFNN^!15~}{woo_!4?!13~!11?!14~!43?!15~!6?-!17?@BNN^!34~}}{wwwooo!6_!12?!7_oOO!18?v!39~w!91?_o!15~!31?!13~!23?_w{}!13~^NFB!34?BFN!13~}{w_!13?!13~!22?@@BFNN^!14~}{{!13~!11?!14~!38?__ow}!14~^!6?-!24?@BBBFFNNN!5^!35~!4^!4NFFFBBB@@!18?_ow}!38~^N!40?__ow{{}!59~^NB!31?!12~^!18?_o{}!14~NFB@!42?@BN^!13~}wo_!8?!13~!30?@@BFNN^!22~!11?!67~^NF@!7?-!43?!23@!33?__oow{}!39~^NF@!34?_oow{}}!58~^^^NNFB@@!34?!5~^NNFB@!15?ow{}!14~^FB@!52?BFN^!12~}{o_!4?!13~!38?@BBFN^^!14~!11?^!56~^^^NNFBB@!12?-!88?__ooww{{}!41~^NFFB@!147?NFB@!281?-!72?___oooww{{{}}!43~^NNFFBB@!440?-!53?!4_ooowww{{{}}}!46~^^NNFFBB@@@!450?-!33?___!4owww!4{}}}!49~^^^NNFFFBBB@@!464?-!21?_oww{}}}!50~^^^!4NFFFBBB@@@!481?-!13?__ow{}}!35~!4^!4N!4F!5B@@@!501?-!7?oow{}~~!12^!7N!7F!5B!5@!526?-!576?'
# --- BANNER-ART-END
$BannerOnly = ($args -contains "-BannerOnly") -or ($args -contains "--banner-only") -or ("$env:NEBFLOW_BANNER_ONLY" -eq "1")
$BannerTheme = "dark"
if ($env:NEBFLOW_BANNER_THEME -eq "light" -or $env:NEBFLOW_BANNER_THEME -eq "dark") {
    $BannerTheme = $env:NEBFLOW_BANNER_THEME
} elseif ($env:COLORFGBG -match "(\d+)\s*$") {
    # Same heuristic the bash installer uses: COLORFGBG's background field
    # >= 7 means a light terminal background (uncommon on Windows; the env
    # override and the dark default cover everything else).
    if ([int]$Matches[1] -ge 7) { $BannerTheme = "light" }
}
$BannerLevel = 0
if (-not ($env:NO_COLOR -or $env:CI -or [Console]::IsOutputRedirected)) {
    if ($env:NEBFLOW_UI_LEVEL -match "^[0-3]$") { $BannerLevel = [int]$env:NEBFLOW_UI_LEVEL }
    elseif ($PSVersionTable.PSVersion.Major -ge 7 -or $env:WT_SESSION) { $BannerLevel = 3 } else { $BannerLevel = 1 }
}
$BannerEsc = "$([char]27)"

function Resolve-BannerImageProto {
    # Dual-path image detector (2026-10-22 batch): "$null" -> block art;
    # "osc" -> OSC 1337 inline PNG; "sixel" -> sixel raster. Fail-closed:
    # anything unrecognized yields the art path, so old conhost NEVER sees
    # escape bytes it cannot render.
    $forced = "$env:NEBFLOW_BANNER_IMAGE"
    if ($forced -in @("off", "0", "no")) { return $null }
    if ($forced -in @("osc", "iterm")) { return "osc" }    # testing: bypasses guards
    if ($forced -in @("sixel", "wt")) { return "sixel" }   # testing: bypasses guards
    if ($forced -ne "" -and $forced -ne $null -and
        $forced -notin @("auto", "yes", "1", "on")) { return $null }
    # auto honors the same guards as the color levels: a redirected pipe or
    # a no-color contract must never receive sixel/OSC bytes.
    if ($env:NO_COLOR -or $env:CI -or $env:TERM -eq "dumb" -or
        [Console]::IsOutputRedirected) { return $null }
    if (@("iTerm.app", "WezTerm", "mintty") -contains $env:TERM_PROGRAM) { return "osc" }
    if ("$env:KONSOLE_VERSION" -match "^\d{6,}$" -and [int]"$env:KONSOLE_VERSION" -ge 220401) {
        return "osc"   # Konsole >= 22.04 renders OSC 1337
    }
    if (-not [string]::IsNullOrEmpty($env:WT_SESSION)) { return "sixel" }
    return $null
}

function Write-Banner {
    # Dual path: a real-image protocol (Resolve-BannerImageProto) renders
    # the OFFICIAL logo raster; everything else gets the half-block cells
    # painted with the theme's ink FOREGROUND color (the terminal background
    # shows through the empty cells). PS 5.1 conhost (level 1) has no VT:
    # one Write-Host per row with -ForegroundColor; VT levels (3/2) inline
    # the escape. Monochrome ink means no per-cell color switching - one
    # paint per row.
    $proto = Resolve-BannerImageProto
    if ($null -ne $proto) {
        if ($BannerTheme -eq "light") { $png = $BannerPngLight; $sixel = $BannerSixelLight }
        else { $png = $BannerPngDark; $sixel = $BannerSixelDark }
        if ($proto -eq "osc") {
            # OSC 1337 inline image; width/height in CELLS. 72x9 cells is
            # physically 4:1 (a cell is ~1:2 w:h) = the lockup's own aspect,
            # on the same footprint as the half-block art (72 cols x 9
            # half-block rows). name= (base64 per the spec) is not
            # decorative: iTerm2's "allow terminal to display this file?"
            # approval keys on it - a named file is remembered once, an
            # unnamed one can prompt again every run.
            Write-Host -NoNewline ("$BannerEsc]1337;File=name=c3RhbmQtbG9nby5wbmc=;inline=1;width=72;height=9:" + $png + [char]7)
        } else {
            # sixel: DCS (aspect default; P2=1 transparent; grid default),
            # the pre-encoded body (raster attrs + palette + RLE bands,
            # canvas 576 x ~144 px = the same 72x9-cell footprint at an
            # ~8x16 cell), ST.
            Write-Host -NoNewline ("$BannerEsc" + "P0;1;0q" + $sixel + $BannerEsc + "\")
        }
        # Version line still sits under the mark - subordinate typography.
        $vline = "$Version installer ($Channel)"
        if ($BannerLevel -ge 1) { Write-Host "  $BannerEsc[2m$vline$BannerEsc[0m" }
        else { Write-Host "  $vline" }
        return
    }
    $ink = if ($BannerTheme -eq "dark") { $BannerInkDark } else { $BannerInkLight }
    $rst = "$BannerEsc[0m"
    $dim = ""
    $fgPrefix = ""
    if ($BannerLevel -eq 3) {
        $fgPrefix = "$BannerEsc[38;2;${ink}m"; $dim = "$BannerEsc[2m"
    } elseif ($BannerLevel -eq 2) {
        # nearest xterm-256: white 231, black 16
        $idx = 16; if ($BannerTheme -eq "dark") { $idx = 231 }
        $fgPrefix = "$BannerEsc[38;5;${idx}m"; $dim = "$BannerEsc[2m"
    } elseif ($BannerLevel -eq 1) {
        $dim = "$BannerEsc[2m"
    }
    $gTop = [string][char]0x2580     # upper half block
    $gBot = [string][char]0x2584     # lower half block
    $gFull = [string][char]0x2588    # full block
    Write-Host ""
    foreach ($row in $BannerArt.Split(";")) {
        $line = New-Object System.Text.StringBuilder
        [void]$line.Append("  ")
        [void]$line.Append($fgPrefix)
        foreach ($tok in [regex]::Matches($row, "(\d+)([.un#])")) {
            $cell = $tok.Groups[2].Value
            $ch = " "
            if ($cell -eq "u") { $ch = $gTop }
            elseif ($cell -eq "n") { $ch = $gBot }
            elseif ($cell -eq "#") { $ch = $gFull }
            [void]$line.Append(([string]$ch) * [int]$tok.Groups[1].Value)
        }
        if ($BannerLevel -ge 1) { [void]$line.Append($rst) }
        if ($BannerLevel -eq 1) {
            # conhost palette: ConsoleColor.White is the brightest white slot
            $fg = [ConsoleColor]::Black
            if ($BannerTheme -eq "dark") { $fg = [ConsoleColor]::White }
            Write-Host $line.ToString() -ForegroundColor $fg
        } else {
            Write-Host $line.ToString()
        }
    }
    # Version line under the art, dim, left-aligned to the lockup edge -
    # typography stays subordinate to the official mark (batch mandate).
    $vline = "$Version installer ($Channel)"
    if ($BannerLevel -ge 1) { Write-Host "  $dim$vline$rst" } else { Write-Host "  $vline" }
    Write-Host ""
}
if ($BannerOnly) {
    # Dry mode: render the banner and exit - zero network, zero install.
    $Version = "dev"
    Write-Banner
    exit 0
}

# Resolve version - mirror version file (single source).
# 2026-09-17 correction: this used to read "GH API unusable since repo went
# private"; the repo is public again, so that reason is stale - the GH API
# branch is retired by the single-source ruling itself, not by repo visibility.
if ($Channel -eq "beta") {
    Write-Info "Resolving latest beta version..."
    if ($env:VERSION) {
        $Version = $env:VERSION
    } else {
        try {
            $BetaVersion = (Invoke-WebRequest -Uri "$CosBaseCn/latest-beta-version.txt" -UseBasicParsing -TimeoutSec 10).Content.Trim()
        } catch {}
        if (-not $BetaVersion) {
            Write-Err2 "Could not find a beta release (COS version file unreachable)."
            Write-Err2 "Check $CosBaseCn/latest-beta-version.txt"
            exit 10
        }
        $Version = $BetaVersion
    }
} else {
    Write-Info "Resolving latest stable version..."
    if ($env:VERSION) {
        $Version = $env:VERSION
    } else {
        try {
            $LatestVersion = (Invoke-WebRequest -Uri "$CosBaseCn/latest-version.txt" -UseBasicParsing -TimeoutSec 10).Content.Trim()
        } catch {}
        if (-not $LatestVersion) {
            Write-Err2 "Could not resolve latest version (COS version file unreachable)."
            Write-Err2 "Check $CosBaseCn/latest-version.txt"
            exit 10
        }
        $Version = $LatestVersion
    }
}
# Version value normalization - dual form accepted (author ruling 2026-09-17):
# the release tag format carries no `v` (e.g. 2026.9.19), but the legacy form
# (pointer file or hand-set value such as v2026.9.19) must still be accepted.
# Strip one leading `v` when a digit follows, so the jar name / URL / install
# dir come out identical in both forms; a prefix-free value is byte-identical
# (idempotent, pure string handling, no new branch beyond this guard).
if ($Version -match '^v[0-9]') {
    Write-V "VERSION carried the legacy 'v' prefix - normalized to $($Version.Substring(1))."
    $Version = $Version.Substring(1)
}
Write-V "Resolved VERSION=$Version (channel=$Channel)"

$InstallDir = if ($env:INSTALL_DIR) { $env:INSTALL_DIR } else { "$env:LOCALAPPDATA\$ProductName" }
$JarName = "$LowerName-assembly-$Version.jar"
$CosUrl = "$CosBaseCn/$JarName"

# --- Brand banner render -----------------------------------------------------
# The Write-Banner definition + official payload sit right after the flag
# parse (search BANNER-ART-BEGIN), so -BannerOnly can render BEFORE version
# resolution; the normal install flow renders here, after resolve, unchanged.
Write-Banner

# --- [1/7] Java (floor 21) ---
Write-Stage 1 7 "Checking Java..."

function Test-Java {
    $savedEAP = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    try {
        $output = & java -version 2>&1 | Out-String
        $match = [regex]::Match($output, '"(\d+)')
        if ($match.Success) {
            $ver = [int]$match.Groups[1].Value
            if ($ver -eq 1) {
                $match2 = [regex]::Match($output, '"1\.(\d+)')
                if ($match2.Success) { $ver = [int]$match2.Groups[1].Value }
            }
            if ($ver -ge $JdkMajorRequired) {
                $ErrorActionPreference = $savedEAP
                return $ver
            }
        }
    } catch {}
    # Fallback: check common install paths (entries below the floor are rejected
    # by the version check)
    $jdkDirs = @(
        "C:\Program Files\Eclipse Adoptium\jdk-17*-hotspot\bin",
        "C:\Program Files\Eclipse Adoptium\jdk-21*-hotspot\bin",
        "C:\Program Files\Temurin\jdk-17*\bin",
        "C:\Program Files\Temurin\jdk-21*\bin",
        "C:\Program Files\Java\jdk-17*\bin",
        "C:\Program Files\Java\jdk-21*\bin"
    )
    foreach ($dir in $jdkDirs) {
        $javaExe = Get-Item (Join-Path $dir "java.exe") -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($javaExe) {
            $output = & $javaExe.FullName -version 2>&1 | Out-String
            $match = [regex]::Match($output, '"(\d+)')
            if ($match.Success) {
                $ver = [int]$match.Groups[1].Value
                if ($ver -ge $JdkMajorRequired) {
                    # Add to PATH so subsequent commands find it
                    $env:Path = "$($javaExe.DirectoryName);$env:Path"
                    $ErrorActionPreference = $savedEAP
                    return $ver
                }
            }
        }
    }
    $ErrorActionPreference = $savedEAP
    return 0
}

$javaVer = Test-Java
if ($javaVer -ge $JdkMajorRequired) {
    $savedEAP = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    $javaLine = & java -version 2>&1 | Select-Object -First 1 | Out-String
    $ErrorActionPreference = $savedEAP
    Write-Ok "Java: $($javaLine.Trim())"
} else {
    Write-Info "Java $JdkMajorRequired+ not found. Installing OpenJDK 21..."

    # Region is needed now to pick the source order; the timezone/locale test
    # is instant (same rule as the Git stage below; no network probe).
    if (-not $Region) {
        $tz = [TimeZoneInfo]::Local.Id
        if ($tz -match "China|Shanghai|Chongqing|Hong_Kong|Taipei|Macau|Urumqi") {
            $Region = "cn"
        } elseif ($env:LANG -match "zh_CN|zh_TW|zh_HK" -or $env:LC_ALL -match "zh_CN|zh_TW|zh_HK") {
            $Region = "cn"
        } else {
            $Region = "global"
        }
    }

    $jdkInstalled = $false
    $jdkMsiName = "OpenJDK21U-jdk_x64_windows_hotspot_21.0.12.1_1.msi"
    $jdkMsiPath = "$env:TEMP\$jdkMsiName"
    # TUNA Adoptium mirror (domestic direct, ~4.3 MB/s measured, first 100 KB
    # byte-identical to the pinned msi) and the Adoptium API (overseas).
    $tunaJdkUrl = "https://mirrors.tuna.tsinghua.edu.cn/Adoptium/21/jdk/x64/windows/$jdkMsiName"
    $adoptiumJdkUrl = "https://api.adoptium.net/v3/binary/latest/21/ga/windows/x64/jdk/hotspot/normal/eclipse"

    function Install-JdkFromMsi([string[]]$Urls) {
        Write-Info "Downloading Temurin JDK 21 msi..."
        if (-not (Get-FileFromSources -Path $jdkMsiPath -Name $jdkMsiName -Urls $Urls)) {
            Write-Warn2 "JDK download failed from the given sources."
            return $false
        }
        Write-Info "Installing JDK 21..."
        $proc = Start-Process msiexec.exe -ArgumentList "/i", $jdkMsiPath, "/quiet", "ADDLOCAL=FeatureMain,FeatureEnvironment,FeatureJarFileRunWith" -Wait -PassThru
        Remove-Item $jdkMsiPath -Force -ErrorAction SilentlyContinue
        if ($proc.ExitCode -eq 0) { return $true }
        Write-Err2 "JDK msi install failed (exit code $($proc.ExitCode))."
        return $false
    }

    function Install-JdkFromWinget {
        $wingetCmd = Get-Command winget -ErrorAction SilentlyContinue
        if (-not $wingetCmd) { return $false }
        Write-Info "Trying winget (EclipseAdoptium.Temurin.21.JDK)..."
        try {
            $proc = Start-Process winget -ArgumentList @(
                "install", "--id", "EclipseAdoptium.Temurin.21.JDK", "-e", "--source", "winget",
                "--silent", "--accept-package-agreements", "--accept-source-agreements"
            ) -Wait -PassThru -NoNewWindow 2>&1
            if ($LASTEXITCODE -eq 0) { return $true }
        } catch {}
        return $false
    }

    # Source order per region (recon R5.3):
    #   cn     = direct msi (deps mirror -> TUNA) -> winget -> Adoptium API
    #   global = winget -> direct msi (deps mirror -> TUNA -> Adoptium API)
    if ($Region -eq "cn") {
        if (-not $jdkInstalled) {
            Write-Info "Trying direct Temurin 21 msi (deps mirror / TUNA, cn)..."
            if (Install-JdkFromMsi @("$CosDepsBase/$jdkMsiName", $tunaJdkUrl)) { $jdkInstalled = $true }
        }
        if (-not $jdkInstalled) {
            if (Install-JdkFromWinget) { $jdkInstalled = $true }
        }
        if (-not $jdkInstalled) {
            Write-Info "Trying Adoptium API msi (overseas last resort, cn)..."
            if (Install-JdkFromMsi @($adoptiumJdkUrl)) { $jdkInstalled = $true }
        }
    } else {
        if (-not $jdkInstalled) {
            if (Install-JdkFromWinget) { $jdkInstalled = $true }
        }
        if (-not $jdkInstalled) {
            Write-Info "Trying direct Temurin 21 msi (deps mirror / TUNA / Adoptium API)..."
            if (Install-JdkFromMsi @("$CosDepsBase/$jdkMsiName", $tunaJdkUrl, $adoptiumJdkUrl)) { $jdkInstalled = $true }
        }
    }

    if (-not $jdkInstalled) {
        Write-Err2 "Manual install: https://adoptium.net/temurin/releases/?version=21 (Windows x64 msi)"
        Write-ChecksumHint "OpenJDK21U-jdk_x64_windows_hotspot_21.0.12.1_1.msi"
        Write-Err2 "Then re-run this installer."
        exit 11
    }

    # Refresh PATH in current session
    $env:Path = [Environment]::GetEnvironmentVariable("Path", "Machine") + ";" + [Environment]::GetEnvironmentVariable("Path", "User")

    $javaVer = Test-Java
    if ($javaVer -lt $JdkMajorRequired) {
        Write-Err2 "JDK installed but not detected. Please restart your terminal and run this script again."
        exit 11
    }
    Write-Ok "JDK 21 installed."
}

# --- [2/7] Git for Windows (provides bash.exe for Bash tool) ---
Write-Stage 2 7 "Checking Git for Windows..."

function Test-GitBash {
    $candidates = @(
        "$env:ProgramFiles\Git\bin\bash.exe",
        "${env:ProgramFiles(x86)}\Git\bin\bash.exe"
    )
    if ($env:LOCALAPPDATA) {
        $candidates += "$env:LOCALAPPDATA\Programs\Git\bin\bash.exe"
    }
    foreach ($path in $candidates) {
        if (Test-Path $path) { return $true }
    }
    # Check PATH but exclude WSL's bash (C:\Windows\System32\bash.exe)
    $bashCmd = Get-Command bash -ErrorAction SilentlyContinue
    if ($bashCmd -and $bashCmd.Source -notlike "*\System32\bash.exe") {
        return $true
    }
    return $false
}

if (Test-GitBash) {
    Write-Ok "Git Bash found"
} else {
    Write-Info "Git Bash not found. Installing Git for Windows..."

    $gitInstalled = $false

    # Method 1: Try winget (cleanest if available)
    $wingetCmd = Get-Command winget -ErrorAction SilentlyContinue
    if ($wingetCmd) {
        Write-Info "Trying winget..."
        try {
            $proc = Start-Process winget -ArgumentList @(
                "install", "--id", "Git.Git", "-e", "--source", "winget",
                "--silent", "--accept-package-agreements", "--accept-source-agreements"
            ) -Wait -PassThru -NoNewWindow 2>&1
            if ($LASTEXITCODE -eq 0 -and (Test-GitBash)) {
                $gitInstalled = $true
            }
        } catch {}
    }

    # Method 2: Direct download with region-aware source selection
    if (-not $gitInstalled) {
        # Determine region (timezone-based, instant - reused by JAR download later)
        if (-not $Region) {
            $tz = [TimeZoneInfo]::Local.Id
            if ($tz -match "China|Shanghai|Chongqing|Hong_Kong|Taipei|Macau|Urumqi") {
                $Region = "cn"
            } elseif ($env:LANG -match "zh_CN|zh_TW|zh_HK" -or $env:LC_ALL -match "zh_CN|zh_TW|zh_HK") {
                $Region = "cn"
            } else {
                $Region = "global"
            }
        }

        $gitVer = "2.55.0.3"
        $gitTag = "v2.55.0.windows.3"
        $gitInstaller = "Git-$gitVer-64-bit.exe"
        $gitPath = "$env:TEMP\$gitInstaller"

        # deps/ mirror is the primary source for every region (batch 2)
        if ($Region -eq "cn") {
            # China: mirror, then npmmirror CDN (~2 MB/s measured; it answers
            # 302 -> cdn.npmmirror.com and the downloader follows redirects by
            # design - a bare redirect page must never pass as the artifact),
            # then proxied GitHub, then GitHub
            $gitMirrors = @(
                "$CosDepsBase/$gitInstaller",
                "https://registry.npmmirror.com/-/binary/git-for-windows/$gitTag/$gitInstaller",
                "https://ghproxy.net/https://github.com/git-for-windows/git/releases/download/$gitTag/$gitInstaller",
                "https://github.com/git-for-windows/git/releases/download/$gitTag/$gitInstaller"
            )
        } else {
            # Global: mirror, then GitHub
            $gitMirrors = @(
                "$CosDepsBase/$gitInstaller",
                "https://github.com/git-for-windows/git/releases/download/$gitTag/$gitInstaller"
            )
        }

        Write-Info "Downloading Git for Windows..."
        if (Get-FileFromSources -Path $gitPath -Name $gitInstaller -Urls $gitMirrors) {
            Write-Info "Installing Git for Windows..."
            $proc = Start-Process $gitPath -ArgumentList "/VERYSILENT", "/NORESTART", "/NOCANCEL", "/SP-", "/CLOSEAPPLICATIONS", "/RESTARTAPPLICATIONS" -Wait -PassThru
            Remove-Item $gitPath -Force -ErrorAction SilentlyContinue

            # Refresh PATH so subsequent checks find bash
            $env:Path = [Environment]::GetEnvironmentVariable("Path", "Machine") + ";" + [Environment]::GetEnvironmentVariable("Path", "User")

            if ($proc.ExitCode -eq 0 -and (Test-GitBash)) {
                Write-Ok "Git for Windows installed."
            } else {
                Write-Err2 "Git install may have failed (exit $($proc.ExitCode))."
                Write-Warn2 "Please install manually: https://git-scm.com/download/win"
            }
        } else {
            Write-Err2 "Git download failed from all sources."
            Write-Warn2 "Please install manually: https://git-scm.com/download/win"
            Write-Warn2 "(Bash tool requires Git for Windows)"
            Write-ChecksumHint $gitInstaller
        }
    }
}

# --- [3/7] Download $ProductName ---
Write-Stage 3 7 "Downloading $ProductName $Version..."

New-Item -ItemType Directory -Force -Path $InstallDir | Out-Null
$jarPath = Join-Path $InstallDir $JarName

if (Test-Path $jarPath) {
    Write-Ok "Already up-to-date ($Version)."
} else {
    # Clean up old versions (keep .nebflow user data untouched)
    $oldJars = @(Get-ChildItem (Join-Path $InstallDir "$LowerName-assembly-*.jar") -ErrorAction SilentlyContinue) + @(Get-ChildItem (Join-Path $InstallDir "nebflow-assembly-*.jar") -ErrorAction SilentlyContinue)
    foreach ($old in $oldJars) {
        if ($old.FullName -ne $jarPath) {
            Remove-Item $old.FullName -Force -ErrorAction SilentlyContinue
            Write-V "Removed old: $($old.Name)"
        }
    }

    # Auto-detect region for download source selection
    if (-not $Region) {
        $tz = [TimeZoneInfo]::Local.Id
        if ($tz -match "China|Shanghai|Chongqing|Hong_Kong|Taipei|Macau|Urumqi") {
            $Region = "cn"
        } elseif ($env:LANG -match "zh_CN|zh_TW|zh_HK" -or $env:LC_ALL -match "zh_CN|zh_TW|zh_HK") {
            $Region = "cn"
        } else {
            # Quick connectivity test: compare latency
            try {
                $cosTime = (Measure-Command {
                    Invoke-WebRequest -Uri "$CosBaseCn/" -UseBasicParsing -TimeoutSec 3 | Out-Null
                }).TotalMilliseconds
            } catch { $cosTime = 9999 }
            try {
                $ghTime = (Measure-Command {
                    Invoke-WebRequest -Uri "https://github.com/favicon.ico" -UseBasicParsing -TimeoutSec 3 | Out-Null
                }).TotalMilliseconds
            } catch { $ghTime = 9999 }
            if ($cosTime -lt 500 -and $cosTime -lt ($ghTime / 2)) {
                $Region = "cn"
            } else {
                $Region = "global"
            }
        }
    }
    Write-Info "Region: $Region (use -Cn or -Global to override)"

    # Single source (conclusion unchanged): the jar comes from the mirror
    # endpoint only. 2026-09-17 correction: the "#29 repo went private ->
    # unauthenticated GitHub Releases 404" reason is stale (the repo is public
    # again) - see the brand-values comment block at the top of this script.
    try {
        Save-WithProgress -Url $CosUrl -Path $jarPath -Label $JarName
    } catch {
        Write-Err2 "Download failed from COS. Check $CosUrl"
        exit 12
    }
    $size = [math]::Round((Get-Item $jarPath).Length / 1MB, 1)
    Write-Ok "Downloaded $JarName from COS ($size MB)."
}

# --- [4/7] ripgrep (rg) for search support ---
Write-Stage 4 7 "Installing ripgrep (rg)..."
if (Get-Command "rg" -ErrorAction SilentlyContinue) {
    Write-Ok "rg already available in PATH."
} elseif (Test-Path (Join-Path $InstallDir "rg.exe")) {
    Write-Ok "rg already cached."
} else {
    $rgName = "ripgrep-$RgVersion-x86_64-pc-windows-msvc.zip"
    $rgZip = Join-Path $InstallDir "rg.zip"
    try {
        Write-Info "Downloading rg $RgVersion..."
        # Source chain: deps/ mirror -> ghproxy -> upstream. ghproxy (~16 KB/s)
        # and upstream (~14 KB/s) are both slow - the real fix is the populated
        # deps/ mirror; ghproxy sits above upstream because upstream is slower
        # AND unreachable on some domestic networks.
        $rgUrls = @(
            "$CosDepsBase/$rgName",
            "https://ghproxy.net/https://github.com/BurntSushi/ripgrep/releases/download/$RgVersion/$rgName",
            "https://github.com/BurntSushi/ripgrep/releases/download/$RgVersion/$rgName"
        )
        if (-not (Get-FileFromSources -Path $rgZip -Name $rgName -Urls $rgUrls)) {
            throw "all sources failed"
        }
        Add-Type -AssemblyName System.IO.Compression.FileSystem
        $zip = [System.IO.Compression.ZipFile]::OpenRead($rgZip)
        $entry = $zip.Entries | Where-Object { $_.Name -eq "rg.exe" } | Select-Object -First 1
        if ($entry) {
            [System.IO.Compression.ZipFileExtensions]::ExtractToFile($entry, (Join-Path $InstallDir "rg.exe"), $true)
            Write-Ok "rg installed to $InstallDir"
        }
        $zip.Dispose()
        Remove-Item $rgZip -Force -ErrorAction SilentlyContinue
    } catch {
        Write-Warn2 "rg download failed: $_"
        Write-Warn2 "Search will rely on PATH install."
        # Upstream ripgrep tags are BARE ("14.1.1"), never "v14.1.1": the old
        # `tag/v$RgVersion` form 404s (tagfix 2026-09-17, curl -I readings).
        Write-Warn2 "Manual download: https://github.com/BurntSushi/ripgrep/releases/tag/$RgVersion"
        Write-Warn2 "Manual placement: extract rg.exe to $InstallDir\rg.exe"
        Write-ChecksumHint $rgName
    }
}

# --- [5/7] Whisper voice model (best-effort) ---
Write-Stage 5 7 "Voice model (Whisper, ~75MB one-time)..."
$modelDir = Join-Path $StandBase "voice-models\onnx-community\whisper-base"
$onnxEncPath = Join-Path $modelDir "onnx\encoder_model_quantized.onnx"

if (Test-Path $onnxEncPath) {
    Write-V "Already installed."
} else {
    # Determine mirror
    if (-not $Region) { $Region = "global" }
    $hfBase = if ($Region -eq "cn") {
        "https://hf-mirror.com/onnx-community/whisper-base/resolve/main"
    } else {
        "https://huggingface.co/onnx-community/whisper-base/resolve/main"
    }

    New-Item -ItemType Directory -Force -Path (Join-Path $modelDir "onnx") | Out-Null

    # Download config files (small)
    $configFiles = @("config.json", "tokenizer.json", "generation_config.json", "preprocessor_config.json")
    foreach ($cf in $configFiles) {
        $target = Join-Path $modelDir $cf
        if (-not (Test-Path $target)) {
            try { Invoke-WebRequest -Uri "$hfBase/$cf" -OutFile $target -UseBasicParsing -TimeoutSec 15 } catch {}
        }
    }

    # Download quantized ONNX models (encoder ~22MB + decoder ~51MB)
    # [n/6] multi-file counter: 4 config files above + these 2
    Write-Info "Downloading model..."
    $dlOk = $true
    try {
        Save-WithProgress -Url "$hfBase/onnx/encoder_model_quantized.onnx" -Path $onnxEncPath -Label "[5/6] encoder_model_quantized.onnx"
    } catch { $dlOk = $false }
    try {
        $decPath = Join-Path $modelDir "onnx\decoder_model_merged_quantized.onnx"
        Save-WithProgress -Url "$hfBase/onnx/decoder_model_merged_quantized.onnx" -Path $decPath -Label "[6/6] decoder_model_merged_quantized.onnx"
    } catch { $dlOk = $false }
    if ($dlOk) {
        Write-Ok "Voice model installed."
    } else {
        Write-Warn2 "Download failed (voice will use CDN on first use)."
    }
}

# --- [6/7] Create wrapper scripts ---
Write-Stage 6 7 "Creating launcher..."

# PowerShell wrapper
# Java selection: the pinned JDK (jdk-21) wins; PATH java is only a fallback.
# A version assertion runs before the JAR is launched (floor = $JdkMajorRequired).
$wrapperPath = Join-Path $InstallDir "$WrapperName.ps1"
$wrapperContent = @"
# >>> WINSORT-BEGIN v1 (version-order jar pick) >>>
# Name order != version order: the date scheme deliberately strips leading zeros
# (Windows version fields reject them), so as plain strings "2026.10.5" sorts
# BEFORE "2026.9.19". Rank the candidates by the parsed numeric tuple (year,
# month, day, same-day -beta.N sequence) and take the max.
# Version core = the SAME contract as packaging/app-version.sh:36
#   ([0-9]{4})\.([0-9]{1,2})\.([0-9]{1,2})(\.[0-9]+)?(-beta\.[0-9]+)?
# The optional 4th segment and the -beta.N tail are the SAME field (the same-day
# sequence, i.e. the tuple's 4th field): four segments = date core + sequence
# (tagfix 2026-09-17; still anchored, so a 5-field name stays unparseable and is
# excluded like any other unknown shape - no new segment semantics).
# Legacy semver shapes (1.4.1-beta.56) rank by the same 4-field tuple; a name
# that parses as neither is EXCLUDED - deliberately NO silent fall back to name
# order (the "JAR not found" branch below then fires).
function Get-NebflowJarVersionKey {
    param([string]`$Name)
    `$m = [regex]::Match(`$Name, '-assembly-(\d{4})\.(\d{1,2})\.(\d{1,2})(?:\.(\d+))?(?:-beta\.(\d+))?\.jar`$')
    if (-not `$m.Success) {
        `$m = [regex]::Match(`$Name, '-assembly-(\d+)\.(\d+)\.(\d+)(?:\.(\d+))?(?:-beta\.(\d+))?\.jar`$')
    }
    if (-not `$m.Success) { return `$null }
    `$seq = 0
    if (`$m.Groups[4].Success) { `$seq = [int]`$m.Groups[4].Value }
    elseif (`$m.Groups[5].Success) { `$seq = [int]`$m.Groups[5].Value }
    return [pscustomobject]@{
        Year  = [int]`$m.Groups[1].Value
        Month = [int]`$m.Groups[2].Value
        Day   = [int]`$m.Groups[3].Value
        Seq   = `$seq
    }
}
function Get-NebflowNewestJar {
    param([object[]]`$Candidates)
    `$ranked = @()
    foreach (`$c in @(`$Candidates)) {
        if (`$null -eq `$c) { continue }
        `$k = Get-NebflowJarVersionKey `$c.Name
        if (`$null -eq `$k) { continue }
        `$ranked += [pscustomobject]@{ Jar = `$c; Year = `$k.Year; Month = `$k.Month; Day = `$k.Day; Seq = `$k.Seq }
    }
    if (@(`$ranked).Count -eq 0) { return `$null }
    return (`$ranked | Sort-Object Year, Month, Day, Seq | Select-Object -Last 1).Jar
}
# <<< WINSORT-END v1 <<<
`$jarCandidates = @(Get-ChildItem "`$PSScriptRoot\$LowerName-assembly-*.jar") + @(Get-ChildItem "`$PSScriptRoot\nebflow-assembly-*.jar")
`$jar = Get-NebflowNewestJar `$jarCandidates
if (-not `$jar) {
    Write-Host "ERROR: $ProductName JAR not found in `$PSScriptRoot" -ForegroundColor Red
    exit 1
}
`$javaExe = "`$env:LOCALAPPDATA\$HomeDir\jdk-21\bin\java.exe"
if (-not (Test-Path `$javaExe)) {
    `$pinned = Get-ChildItem -Path "`$env:ProgramFiles\Eclipse Adoptium\jdk-21*-hotspot\bin\java.exe", "`$env:ProgramFiles\Temurin\jdk-21*\bin\java.exe", "`$env:ProgramFiles\Java\jdk-21*\bin\java.exe" -ErrorAction SilentlyContinue | Select-Object -First 1
    if (`$pinned) { `$javaExe = `$pinned.FullName } else { `$javaExe = "java" }
}
`$javaMajor = 0
try {
    `$verOut = & `$javaExe -version 2>&1 | Out-String
    `$verMatch = [regex]::Match(`$verOut, '"(\d+)')
    if (`$verMatch.Success) {
        `$javaMajor = [int]`$verMatch.Groups[1].Value
        if (`$javaMajor -eq 1) {
            `$verMatch2 = [regex]::Match(`$verOut, '"1\.(\d+)')
            if (`$verMatch2.Success) { `$javaMajor = [int]`$verMatch2.Groups[1].Value }
        }
    }
} catch {}
if (`$javaMajor -lt $JdkMajorRequired) {
    Write-Host "ERROR: Java $JdkMajorRequired+ is required, but the launcher java is: `$javaExe" -ForegroundColor Red
    Write-Host "  Install:  winget install --id EclipseAdoptium.Temurin.21.JDK -e" -ForegroundColor Red
    Write-Host "  Download: https://adoptium.net/temurin/releases/?version=21" -ForegroundColor Red
    Write-Host "  Then re-run: $WrapperName <command>" -ForegroundColor Red
    exit 11
}
& `$javaExe --add-opens java.base/java.lang=ALL-UNNAMED -jar `$jar.FullName `$args
"@
Set-Content -Path $wrapperPath -Value $wrapperContent -Encoding UTF8
Write-Ok "Wrapper created: $wrapperPath"

# CMD wrapper
# Java selection: the pinned JDK (jdk-21) wins; PATH java is only a fallback.
# PATH is no longer mutated, and no jdk-17 entry is added any more.
$cmdPath = Join-Path $InstallDir "$WrapperName.cmd"
$cmdContent = @"
@echo off
setlocal
set "JAVA_DIR="
if exist "%LOCALAPPDATA%\$HomeDir\jdk-21\bin\java.exe" set "JAVA_DIR=%LOCALAPPDATA%\$HomeDir\jdk-21\bin"
if not defined JAVA_DIR for /d %%d in ("C:\Program Files\Eclipse Adoptium\jdk-21*") do if not defined JAVA_DIR if exist "%%~d\bin\java.exe" set "JAVA_DIR=%%~d\bin"
if not defined JAVA_DIR for /d %%d in ("C:\Program Files\Temurin\jdk-21*" "C:\Program Files\Java\jdk-21*") do if not defined JAVA_DIR if exist "%%~d\bin\java.exe" set "JAVA_DIR=%%~d\bin"
if defined JAVA_DIR pushd "%JAVA_DIR%"
set "JVERFILE=%TEMP%\nebflow_java_ver.txt"
if "%TEMP%"=="" set "JVERFILE=%USERPROFILE%\nebflow_java_ver.txt"
set "JV="
java -version > "%JVERFILE%" 2>&1
for /f "tokens=3" %%v in ('findstr /i version "%JVERFILE%"') do if not defined JV set "JV=%%~v"
del "%JVERFILE%" 2>nul
if not defined JV set "JV=not found"
set "JMAJ=0"
for /f "tokens=1,2 delims=." %%a in ("%JV%") do (set "JMAJ=%%a" & set "JMIN=%%b")
if "%JMAJ%"=="1" set "JMAJ=%JMIN%"
set /a JAVA_MAJOR=%JMAJ%+0 2>nul
if not defined JAVA_MAJOR set "JAVA_MAJOR=0"
if %JAVA_MAJOR% LSS $JdkMajorRequired goto java_too_old
set "JAR="
set "NB_JARKEY="
for %%f in ("%~dp0nebflow-assembly-*.jar" "%~dp0$LowerName-assembly-*.jar") do call :nebflow_pick_jar "%%~f"
if "%JAR%"=="" (
    echo ERROR: %~dp0 JAR not found
    exit /b 1
)
java --add-opens java.base/java.lang=ALL-UNNAMED -jar "%JAR%" %*
exit /b %ERRORLEVEL%

:java_too_old
if not defined JAVA_DIR set "JAVA_DIR=java on PATH - no pinned jdk-21 found"
echo ERROR: Java $JdkMajorRequired+ is required, but this launcher found: %JV%
echo   java source: %JAVA_DIR%
echo   Install:  winget install --id EclipseAdoptium.Temurin.21.JDK -e
echo   Download: https://adoptium.net/temurin/releases/?version=21
echo   Then re-run: $WrapperName ^<command^>
exit /b 11

:nebflow_pick_jar
rem >>> WINSORT-BEGIN v1 (version-order jar pick) >>>
rem Name order != version order: the date scheme deliberately strips leading
rem zeros (Windows version fields reject them), so as plain strings "2026.10.5"
rem sorts BEFORE "2026.9.19". Rank the candidate (arg %~1) by the parsed numeric
rem tuple and keep the max. Version core = the SAME contract as
rem packaging/app-version.sh:36
rem   ([0-9]{4})\.([0-9]{1,2})\.([0-9]{1,2})(\.[0-9]+)?(-beta\.[0-9]+)?
rem The optional 4th segment and the -beta.N tail are the SAME field (the
rem same-day sequence, i.e. the tuple's 4th field): four segments = date core +
rem sequence; still anchored, so a 5-field name stays unparseable (tagfix
rem 2026-09-17, no new segment semantics).
rem Legacy semver shapes (1.4.1-beta.56) rank by the same 4-field tuple; a name
rem that parses as neither is EXCLUDED - deliberately NO silent fall back to
rem name order (the "JAR not found" branch above then fires).
rem Numeric fields are zero-padded to 4/3/3/6 columns so that a plain string
rem compare IS the version compare; the leading "k" only keeps cmd's IF from
rem taking the numeric-reinterpretation path on the 16-digit key.
set "NB_NAME=%~nx1"
set "NB_VER="
set "NB_CORE="
set "NB_TAIL="
set "NB_SEQ=0"
set "NB_SEQ4="
set "NB_Y="
set "NB_M="
set "NB_D="
set "NB_KEY="
set "NB_VER=%NB_NAME:*-assembly-=%"
if "%NB_VER%"=="%NB_NAME%" exit /b 0
rem %~nx1 keeps the extension: strip ".jar" first, else it is read as a bogus
rem 4th dot-field ("2026.9.19.jar" -> 2026 / 9 / 19 / jar).
set "NB_VER=%NB_VER:.jar=%"
for /f "tokens=1,* delims=-" %%a in ("%NB_VER%") do (
  set "NB_CORE=%%a"
  set "NB_TAIL=%%b"
)
if defined NB_TAIL (
  if /i not "%NB_TAIL:~0,5%"=="beta." exit /b 0
  set "NB_SEQ=%NB_TAIL:beta.=%"
)
rem Date core + optional same-day sequence: 3 or 4 numeric fields; 5+ = reject
rem (the "*" token = "all remaining text", the early exit is on THAT, not on the
rem 4th field any more).
for /f "tokens=1,2,3,4,* delims=." %%a in ("%NB_CORE%") do (
  if not "%%~e"=="" exit /b 0
  set "NB_Y=%%a"
  set "NB_M=%%b"
  set "NB_D=%%c"
  set "NB_SEQ4=%%d"
)
rem 4th field = the same-day sequence (the slot the -beta.N tail fills); a
rem missing or non-numeric 4th field leaves the tail's value untouched.
if defined NB_SEQ4 if not "%NB_SEQ4%"=="" for /f "delims=0123456789" %%z in ("%NB_SEQ4%") do set "NB_SEQ4="
if defined NB_SEQ4 if not "%NB_SEQ4%"=="" set "NB_SEQ=%NB_SEQ4%"
if not defined NB_Y exit /b 0
if not defined NB_M exit /b 0
if not defined NB_D exit /b 0
for /f "delims=0123456789" %%z in ("%NB_Y%") do exit /b 0
for /f "delims=0123456789" %%z in ("%NB_M%") do exit /b 0
for /f "delims=0123456789" %%z in ("%NB_D%") do exit /b 0
for /f "delims=0123456789" %%z in ("%NB_SEQ%") do exit /b 0
if not "%NB_Y:~4%"=="" exit /b 0
if not "%NB_M:~3%"=="" exit /b 0
if not "%NB_D:~3%"=="" exit /b 0
if not "%NB_SEQ:~6%"=="" exit /b 0
set "NB_YY=000%NB_Y%"
set "NB_MM=000%NB_M%"
set "NB_DD=000%NB_D%"
set "NB_SS=000000%NB_SEQ%"
set "NB_KEY=k%NB_YY:~-4%%NB_MM:~-3%%NB_DD:~-3%%NB_SS:~-6%"
if not defined NB_JARKEY (
  set "NB_JARKEY=%NB_KEY%"
  set "JAR=%~f1"
  exit /b 0
)
if "%NB_KEY%" GTR "%NB_JARKEY%" (
  set "NB_JARKEY=%NB_KEY%"
  set "JAR=%~f1"
)
exit /b 0
rem <<< WINSORT-END v1 <<<
"@
Set-Content -Path $cmdPath -Value $cmdContent -Encoding ASCII

# Legacy command shim (2026-10-20 rename batch): "nebflow" is retired as the
# command name; this thin .cmd warns on stderr, then forwards to the current
# launcher. Fixed legacy name by design (historical fact, like rebrand.sh).
$shimPath = Join-Path $InstallDir "nebflow.cmd"
$shimContent = @"
@echo off
echo WARN: 'nebflow' is deprecated - the command is now '$WrapperName'. Forwarding... 1>&2
"%~dp0$WrapperName.cmd" %*
exit /b %ERRORLEVEL%
"@
Set-Content -Path $shimPath -Value $shimContent -Encoding ASCII

# Add to PATH
$userPath = [Environment]::GetEnvironmentVariable("Path", "User")
if ($userPath -notlike "*$InstallDir*") {
    [Environment]::SetEnvironmentVariable("Path", "$userPath;$InstallDir", "User")
    Write-Ok "Added to PATH"
}

# --- [7/7] Config + install manifest ---
Write-Stage 7 7 "Setting up config..."

$configDir = $StandBase
$configPath = Join-Path $configDir "$ConfigFile"
if (-not (Test-Path $configPath)) {
    New-Item -ItemType Directory -Force -Path $configDir | Out-Null
    $configContent = "{}"
    [System.IO.File]::WriteAllText($configPath, $configContent)
    Write-Ok "Config created: $configPath"
    Write-Warn2 "Please edit it to set your API key."
} else {
    Write-V "Config already exists."
}

# Installer manifest (ScriptVersion + environment) for `nebflow update`
# and diagnostics. Overwritten on each (re)install.
if (-not $Region) { $Region = "global" }
$manifestPath = Join-Path $configDir "install-manifest.json"
$manifest = @"
{
  "scriptVersion": "$ScriptVersion",
  "product": "$ProductName",
  "version": "$Version",
  "channel": "$Channel",
  "region": "$Region",
  "os": "windows",
  "arch": "x64",
  "installDir": "$($InstallDir.Replace('\', '\\'))",
  "installedAt": "$((Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ'))"
}
"@
[System.IO.File]::WriteAllText($manifestPath, $manifest)
Write-V "Manifest written: $manifestPath"

# --- Done ---
Write-Host ""
Write-Host "[ok] $ProductName $Version installed!" -ForegroundColor Green
Write-Host ""
Write-Host "  Commands:" -ForegroundColor White
Write-Host "    $WrapperName --help" -ForegroundColor Cyan
Write-Host "    $WrapperName start" -ForegroundColor Cyan
Write-Host ""
Write-Host "  Config: $StandBase\$ConfigFile" -ForegroundColor DarkGray
Write-Host ""
Write-Host "  NOTE: Restart your terminal for PATH to take effect." -ForegroundColor Yellow
Write-Host ""
if ([Console]::IsInputRedirected -eq $false) {
    Read-Host "Press Enter to exit"
}